(function(){'use strict';const safe=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function api(path,data){const r=await fetch('/api/auth/'+path,{method:data?'POST':'GET',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-Top-Hills':'1'},body:data?JSON.stringify(data):undefined});const v=await r.json();if(!r.ok)throw Error(v.error||'Permintaan gagal.');return v;}function notice(s){if(window.toast)toast(s);else alert(window.THCopy?THCopy.error(s):s);}window.THSession={async logout(){try{const v=await api('logout',{});sessionStorage.removeItem('th-session-ui');location.assign(v.redirect);}catch(e){notice(e.message)}},async manage(){try{const v=await api('sessions');const d=document.createElement('dialog');d.innerHTML='<h2>Sesi perangkat Anda</h2><p>Sesi berakhir setelah 12 jam tidak aktif atau maksimal 7 hari. Catatan usaha tetap tersimpan.</p>'+v.sessions.map(s=>`<div class="card"><strong>${s.current?'Perangkat ini':'Perangkat lain'}</strong><p>${safe(s.device)}</p><small>Aktif ${new Date(s.last_seen).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'})} WIB</small>${s.current?'':`<p><button data-revoke="${safe(s.id)}">Keluarkan perangkat</button></p>`}</div>`).join('')+'<div class="row"><button id="all-sessions">Keluar dari semua perangkat</button><button id="close-sessions">Tutup</button></div>';document.body.append(d);d.showModal();d.querySelector('#close-sessions').onclick=()=>d.close();d.addEventListener('close',()=>d.remove());d.querySelectorAll('[data-revoke]').forEach(b=>b.onclick=async()=>{try{b.disabled=true;await api('revoke',{id:b.dataset.revoke});b.closest('.card').remove()}catch(e){b.disabled=false;notice(e.message)}});d.querySelector('#all-sessions').onclick=async()=>{if(!confirm('Keluarkan semua sesi login email Top Hills Anda?'))return;await api('revoke',{all:true});location.assign('/login')};}catch(e){notice(e.message)}}};document.addEventListener('click',e=>{if(e.target.closest('[data-th-logout]'))THSession.logout();if(e.target.closest('[data-th-sessions]'))THSession.manage();});window.addEventListener('pageshow',e=>{if(e.persisted)location.reload()});})();
